def create_document(workspace_id, collection_id, title, text, parent_document_id=None, status=None, published_at=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_document"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid date-time format", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _append_request_log(status_code, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"out_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso(_now()),
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        policy = _load("rate_limits.json")
        if not isinstance(policy, list) or not policy:
            return None
        p = None
        for r in policy:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                p = r
                break
        if not p:
            return None
        window_s = p.get("window_seconds")
        limit_ = p.get("limit")
        if not isinstance(window_s, int) or not isinstance(limit_, int) or window_s <= 0 or limit_ <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= limit_:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate inputs
    try:
        rl = _enforce_rate_limit()
        if rl:
            _append_request_log("RATE_LIMIT")
            return rl

        if not isinstance(workspace_id, str) or not re.match(r"^out_ws_[0-9A-Z]{18,}$", workspace_id):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")
        if not isinstance(collection_id, str) or not re.match(r"^out_col_[0-9A-Z]{18,}$", collection_id):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "collection_id is malformed", field="collection_id")
        if parent_document_id is not None and (not isinstance(parent_document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", parent_document_id)):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_document_id is malformed", field="parent_document_id")
        if not isinstance(title, str) or title.strip() == "":
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
        if not isinstance(text, str):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "text must be a string", field="text")
        if status is not None:
            if not isinstance(status, str) or status not in ("draft", "published", "archived"):
                _append_request_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "status must be one of: draft, published, archived", field="status")
        pub_dt, pub_err = _parse_dt(published_at, "published_at")
        if pub_err:
            _append_request_log("VALIDATION_ERROR")
            return pub_err

        if status == "published":
            if pub_dt is None:
                pub_dt = _now()
        else:
            # If not published, ignore any provided published_at (but validate format above)
            pub_dt = None

        # Load required references
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            _append_request_log("NOT_FOUND")
            return _err("NOT_FOUND", "Workspace not found", field="workspace_id")
        if ws.get("status") == "deleted":
            _append_request_log("NOT_FOUND")
            return _err("NOT_FOUND", "Workspace not found", field="workspace_id")

        collections = _load("collections.json")
        if not isinstance(collections, list):
            collections = []
        col = next((c for c in collections if isinstance(c, dict) and c.get("id") == collection_id), None)
        if not col:
            _append_request_log("NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found", field="collection_id")
        if col.get("status") == "deleted":
            _append_request_log("CONFLICT")
            return _err("CONFLICT", "Cannot create document in a deleted collection", field="collection_id")
        # Business rule: workspace_id must match collection.workspace_id
        if col.get("workspace_id") != workspace_id:
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must equal collections.workspace_id for the referenced collection_id", field="workspace_id")

        documents = _load("documents.json")
        if not isinstance(documents, list):
            documents = []

        # Parent document constraints
        parent_doc = None
        if parent_document_id is not None:
            parent_doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == parent_document_id), None)
            if not parent_doc:
                _append_request_log("NOT_FOUND")
                return _err("NOT_FOUND", "Parent document not found", field="parent_document_id")
            if parent_doc.get("status") == "deleted":
                _append_request_log("CONFLICT")
                return _err("CONFLICT", "Parent document is deleted", field="parent_document_id")
            if parent_doc.get("workspace_id") != workspace_id:
                _append_request_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_document_id implies parent document workspace_id = documents.workspace_id", field="parent_document_id")

        # Uniqueness: unique(collection_id, title) where status <> 'deleted'
        for d in documents:
            if not isinstance(d, dict):
                continue
            if d.get("collection_id") == collection_id and d.get("title") == title and d.get("status") != "deleted":
                _append_request_log("CONFLICT")
                return _err("CONFLICT", "A non-deleted document with this title already exists in the collection", field="title")

        # Generate ids
        def _gen_id(prefix, existing_ids):
            # time-based + counter to avoid collisions
            base = int(time.time() * 1000)
            i = 0
            while True:
                cand = f"{prefix}_{base}{i:03d}"
                if cand not in existing_ids:
                    return cand
                i += 1

        existing_doc_ids = {d.get("id") for d in documents if isinstance(d, dict)}
        doc_id = _gen_id("out_doc", existing_doc_ids)

        now_iso = _iso(_now())
        doc_status = status or "draft"
        doc_row = {
            "id": doc_id,
            "workspace_id": workspace_id,
            "collection_id": collection_id,
            "parent_document_id": parent_document_id,
            "title": title,
            "text": text,
            "version": 1,
            "published_at": _iso(pub_dt) if pub_dt else None,
            "status": doc_status,
            "created_at": now_iso,
            "updated_at": now_iso,
            "deleted_at": None,
        }

        # Create revision v1 (snapshot of created doc)
        revisions = _load("document_revisions.json")
        if not isinstance(revisions, list):
            revisions = []
        existing_rev_ids = {r.get("id") for r in revisions if isinstance(r, dict)}
        rev_id = _gen_id("out_rev", existing_rev_ids)
        rev_row = {
            "id": rev_id,
            "document_id": doc_id,
            "workspace_id": workspace_id,
            "version": 1,
            "title": title,
            "text": text,
            "collection_id": collection_id,
            "parent_document_id": parent_document_id,
            "created_at": now_iso,
        }

        # Create/update search index row to active
        sidx = _load("document_search_index.json")
        if not isinstance(sidx, list):
            sidx = []
        existing_sidx = next((r for r in sidx if isinstance(r, dict) and r.get("document_id") == doc_id), None)

        def _norm(s):
            return " ".join(str(s).lower().split())

        if existing_sidx:
            # shouldn't happen for new doc_id, but keep consistent/idempotent-ish
            existing_sidx["workspace_id"] = workspace_id
            existing_sidx["collection_id"] = collection_id
            existing_sidx["title_normalized"] = _norm(title)
            existing_sidx["content_normalized"] = _norm(text)
            existing_sidx["last_indexed_version"] = 1
            existing_sidx["status"] = "active"
            existing_sidx["updated_at"] = now_iso
        else:
            existing_sidx_ids = {r.get("id") for r in sidx if isinstance(r, dict)}
            sidx_id = _gen_id("out_sidx", existing_sidx_ids)
            sidx.append({
                "id": sidx_id,
                "document_id": doc_id,
                "workspace_id": workspace_id,
                "collection_id": collection_id,
                "title_normalized": _norm(title),
                "content_normalized": _norm(text),
                "last_indexed_version": 1,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            })

        # Persist
        documents.append(doc_row)
        revisions.append(rev_row)
        _save("documents.json", documents)
        _save("document_revisions.json", revisions)
        _save("document_search_index.json", sidx)

        _append_request_log("OK", workspace_id=workspace_id, collection_id=collection_id, document_id=doc_id)
        return {"document": doc_row}
    except Exception as e:
        _append_request_log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def delete_document(document_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    req_logs = _load("request_logs.json")
    usage = _load("usage.json")

    def _log(status_code, extra=None):
        elapsed_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"out_req_{int(time.time()*1000)}",
            "endpoint": "delete_document",
            "timestamp": now,
            "status": status_code,
            "latency_ms": elapsed_ms,
            "credential_id": None,
        }
        if extra:
            row.update(extra)
        if isinstance(req_logs, list):
            req_logs.append(row)
            _save("request_logs.json", req_logs)
        if isinstance(usage, list) and usage:
            u0 = usage[0]
            if isinstance(u0, dict):
                u0["requests"] = int(u0.get("requests", 0) or 0) + 1
                _save("usage.json", usage)

    if not isinstance(document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", document_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "document_id is missing or malformed", field="document_id")

    documents = _load("documents.json")
    search_index = _load("document_search_index.json")

    doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id), None)
    if not doc:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "document not found", document_id=document_id)

    if doc.get("status") == "deleted":
        _log("CONFLICT")
        return _err("CONFLICT", "document is already deleted", document_id=document_id)

    # Soft delete document
    doc["status"] = "deleted"
    doc["deleted_at"] = now
    doc["updated_at"] = now
    # version does not need to change for delete in rules

    # Mark search index as deleted (if exists)
    idx = next((x for x in search_index if isinstance(x, dict) and x.get("document_id") == document_id), None)
    if idx:
        idx["status"] = "deleted"
        idx["updated_at"] = now

    _save("documents.json", documents)
    _save("document_search_index.json", search_index)

    _log("OK", extra={"document_id": document_id, "workspace_id": doc.get("workspace_id")})
    return {"data": doc}

def get_document(document_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    req_logs = _load("request_logs.json")
    usage = _load("usage.json")

    def _log(status_code, extra=None):
        elapsed_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"out_req_{int(time.time()*1000)}",
            "endpoint": "get_document",
            "timestamp": now,
            "status": status_code,
            "latency_ms": elapsed_ms,
            "credential_id": None,
        }
        if extra:
            row.update(extra)
        if isinstance(req_logs, list):
            req_logs.append(row)
            _save("request_logs.json", req_logs)
        if isinstance(usage, list) and usage:
            u0 = usage[0]
            if isinstance(u0, dict):
                u0["requests"] = int(u0.get("requests", 0) or 0) + 1
                _save("usage.json", usage)

    if not isinstance(document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", document_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "document_id is missing or malformed", field="document_id")

    documents = _load("documents.json")
    doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id), None)
    if not doc:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "document not found", document_id=document_id)

    # Exclude deleted by default
    if doc.get("status") == "deleted":
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "document not found", document_id=document_id)

    _log("OK", extra={"document_id": document_id, "workspace_id": doc.get("workspace_id")})
    return {"data": doc}

def list_documents(collection_id, limit=None, cursor=None, status=None, parent_document_id=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    req_logs = _load("request_logs.json")
    usage = _load("usage.json")

    def _log(status_code, extra=None):
        elapsed_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"out_req_{int(time.time()*1000)}",
            "endpoint": "list_documents",
            "timestamp": now,
            "status": status_code,
            "latency_ms": elapsed_ms,
            "credential_id": None,
        }
        if extra:
            row.update(extra)
        if isinstance(req_logs, list):
            req_logs.append(row)
            _save("request_logs.json", req_logs)
        if isinstance(usage, list) and usage:
            u0 = usage[0]
            if isinstance(u0, dict):
                u0["requests"] = int(u0.get("requests", 0) or 0) + 1
                _save("usage.json", usage)

    if not isinstance(collection_id, str) or not re.match(r"^out_col_[0-9A-Z]{18,}$", collection_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_id is missing or malformed", field="collection_id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    allowed_status = {"draft", "published", "archived", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid", field="status", allowed=sorted(list(allowed_status)))

    if parent_document_id is not None:
        if not isinstance(parent_document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", parent_document_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_document_id is malformed", field="parent_document_id")

    allowed_sort = {"created_at", "updated_at", "published_at", "title", "position"}
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort", allowed=sorted(list(allowed_sort)))

    allowed_order = {"asc", "desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid", field="order", allowed=sorted(list(allowed_order)))

    collections = _load("collections.json")
    documents = _load("documents.json")

    col = next((c for c in collections if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not col or col.get("status") == "deleted":
        # For list: vendor description only calls out validation errors; but NOT_FOUND is consistent with other tools
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "collection not found", collection_id=collection_id)

    # Filter
    rows = []
    for d in documents:
        if not isinstance(d, dict):
            continue
        if d.get("collection_id") != collection_id:
            continue
        # default exclude deleted
        if status is None:
            if d.get("status") == "deleted":
                continue
        else:
            if d.get("status") != status:
                continue
        if parent_document_id is not None:
            if d.get("parent_document_id") != parent_document_id:
                continue
        rows.append(d)

    # Sorting
    reverse = (order == "desc")

    def _dt_or_none(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except ValueError:
            return None

    def _key(d):
        if sort in ("created_at", "updated_at", "published_at"):
            dt = _dt_or_none(d.get(sort))
            # Put None last for asc, first for desc? Prefer None last always for stability.
            return (dt is None, dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        if sort == "title":
            return (d.get("title") or "").lower()
        if sort == "position":
            # documents have no position field in schema; treat as 0
            v = d.get("position")
            try:
                return float(v)
            except Exception:
                return 0.0
        return d.get(sort)

    try:
        rows.sort(key=_key, reverse=reverse)
    except TypeError:
        # Fallback to stable string sort if mixed types appear
        rows.sort(key=lambda d: str(d.get(sort)), reverse=reverse)

    # Cursor pagination: opaque base64 of integer offset
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            start = int(raw.decode("utf-8"))
            if start < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(start + limit).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK", extra={"collection_id": collection_id, "returned": len(page), "total": total})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def move_document(document_id, collection_id, parent_document_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _append_request_log(status_code, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"out_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "move_document",
            "timestamp": _iso(_now()),
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        policy = _load("rate_limits.json")
        if not isinstance(policy, list) or not policy:
            return None
        p = None
        for r in policy:
            if isinstance(r, dict) and r.get("endpoint") == "move_document":
                p = r
                break
        if not p:
            return None
        window_s = p.get("window_seconds")
        limit_ = p.get("limit")
        if not isinstance(window_s, int) or not isinstance(limit_, int) or window_s <= 0 or limit_ <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = _now() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != "move_document":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                if dt >= cutoff:
                    cnt += 1
            except ValueError:
                continue
        if cnt >= limit_:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _append_request_log("RATE_LIMIT")
        return rl

    if not isinstance(document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", document_id):
        _append_request_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "document_id is missing or malformed", field="document_id")
    if not isinstance(collection_id, str) or not re.match(r"^out_col_[0-9A-Z]{18,}$", collection_id):
        _append_request_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_id is missing or malformed", field="collection_id")
    if parent_document_id is not None:
        if not isinstance(parent_document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", parent_document_id):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_document_id is malformed", field="parent_document_id")

    documents = _load("documents.json")
    collections = _load("collections.json")
    revisions = _load("document_revisions.json")
    sindex = _load("document_search_index.json")
    if not isinstance(documents, list):
        documents = []
    if not isinstance(collections, list):
        collections = []
    if not isinstance(revisions, list):
        revisions = []
    if not isinstance(sindex, list):
        sindex = []

    doc_i = None
    doc = None
    for i, d in enumerate(documents):
        if isinstance(d, dict) and d.get("id") == document_id:
            doc_i = i
            doc = d
            break
    if not doc or doc.get("status") == "deleted":
        _append_request_log("NOT_FOUND")
        return _err("NOT_FOUND", "document not found", field="document_id")

    dest = next((c for c in collections if isinstance(c, dict) and c.get("id") == collection_id), None)
    if not dest:
        _append_request_log("NOT_FOUND")
        return _err("NOT_FOUND", "destination collection not found", field="collection_id")
    if dest.get("status") == "deleted":
        _append_request_log("CONFLICT")
        return _err("CONFLICT", "destination collection is deleted", field="collection_id")

    # Must be same workspace
    if dest.get("workspace_id") != doc.get("workspace_id"):
        _append_request_log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "target collection must be in the same workspace as the document", field="collection_id")

    parent_doc = None
    if parent_document_id is not None:
        parent_doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == parent_document_id), None)
        if not parent_doc or parent_doc.get("status") == "deleted":
            _append_request_log("NOT_FOUND")
            return _err("NOT_FOUND", "parent document not found", field="parent_document_id")
        if parent_doc.get("workspace_id") != doc.get("workspace_id"):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_document_id implies parent document workspace_id = documents.workspace_id", field="parent_document_id")

    # If no effective change, return unchanged but still log OK
    if doc.get("collection_id") == collection_id and doc.get("parent_document_id") == parent_document_id:
        _append_request_log("OK", document_id=document_id)
        return {"document": doc}

    now = _now()

    # Append revision capturing move (post-move snapshot)
    def _gen_id(prefix):
        return f"{prefix}{int(time.time()*1000)}{len(revisions)+1:06d}"

    new_version = int(doc.get("version") or 1) + 1
    updated = dict(doc)
    updated["version"] = new_version
    updated["collection_id"] = collection_id
    updated["parent_document_id"] = parent_document_id
    updated["updated_at"] = _iso(now)

    rev_row = {
        "id": _gen_id("out_rev_"),
        "document_id": document_id,
        "workspace_id": updated.get("workspace_id"),
        "version": new_version,
        "title": updated.get("title"),
        "text": updated.get("text"),
        "collection_id": updated.get("collection_id"),
        "parent_document_id": updated.get("parent_document_id"),
        "created_at": _iso(now),
    }

    # Update search index collection_id accordingly (and keep active if it was active; otherwise preserve status unless deleted)
    srow_i = None
    srow = None
    for i, r in enumerate(sindex):
        if isinstance(r, dict) and r.get("document_id") == document_id:
            srow_i = i
            srow = r
            break
    if srow and srow.get("status") != "deleted":
        s2 = dict(srow)
        s2["collection_id"] = collection_id
        s2["updated_at"] = _iso(now)
        # moving typically makes index consistent in collection scope, no need to mark stale for content
        sindex[srow_i] = s2

    documents[doc_i] = updated
    revisions.append(rev_row)
    _save("documents.json", documents)
    _save("document_revisions.json", revisions)
    _save("document_search_index.json", sindex)

    _append_request_log("OK", document_id=document_id)
    return {"document": updated}

def search_documents(workspace_id, query, collection_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"out_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "search_documents",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        policy = _load("rate_limits.json")
        if not isinstance(policy, list) or not policy:
            return None
        p = None
        for r in policy:
            if isinstance(r, dict) and r.get("endpoint") == "search_documents":
                p = r
                break
        if not p:
            return None
        window_s = p.get("window_seconds")
        limit_ = p.get("limit")
        if not isinstance(window_s, int) or not isinstance(limit_, int) or window_s <= 0 or limit_ <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
        cnt = 0
        for r in logs:
            if isinstance(r, dict) and r.get("endpoint") == "search_documents":
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    cnt += 1
        if cnt >= limit_:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT")
        return rl

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^out_ws_[0-9A-Z]{18,}$", workspace_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(query, str) or not query.strip():
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if collection_id is not None and (not isinstance(collection_id, str) or not re.match(r"^out_col_[0-9A-Z]{18,}$", collection_id)):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "collection_id is malformed.")
    if status is not None:
        if status not in ("draft", "published", "archived", "deleted"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "relevance"
    if sort not in ("relevance", "updated_at", "created_at", "published_at"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid.")

    workspaces = _load("workspaces.json")
    collections = _load("collections.json")
    documents = _load("documents.json")
    index = _load("document_search_index.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(collections, list): collections = []
    if not isinstance(documents, list): documents = []
    if not isinstance(index, list): index = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context available to perform this operation.")

    if collection_id is not None:
        col = next((c for c in collections if isinstance(c, dict) and c.get("id") == collection_id), None)
        if not col or col.get("workspace_id") != workspace_id or col.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found.")

    def _normalize(s):
        s = s.lower()
        # lightweight normalization
        out = []
        for ch in s:
            if ch.isalnum() or ch.isspace():
                out.append(ch)
            else:
                out.append(" ")
        return " ".join("".join(out).split())

    qn = _normalize(query)
    terms = [t for t in qn.split() if t]
    if not terms:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must contain searchable terms.")

    doc_by_id = {d.get("id"): d for d in documents if isinstance(d, dict) and isinstance(d.get("id"), str)}
    eligible_statuses = ("draft", "published", "archived")  # per business rules
    matches = []

    for idx in index:
        if not isinstance(idx, dict):
            continue
        if idx.get("workspace_id") != workspace_id:
            continue
        if idx.get("status") != "active":
            continue
        if collection_id is not None and idx.get("collection_id") != collection_id:
            continue
        did = idx.get("document_id")
        doc = doc_by_id.get(did)
        if not doc or doc.get("workspace_id") != workspace_id:
            continue
        if doc.get("status") not in eligible_statuses:
            continue
        if status is not None and doc.get("status") != status:
            continue

        tn = idx.get("title_normalized")
        cn = idx.get("content_normalized")
        if not isinstance(tn, str) or not isinstance(cn, str):
            continue

        # Simple ranking: title hits weighted more than content hits; prefix in title gives bonus.
        score = 0.0
        for t in terms:
            if t in tn:
                score += 5.0
                if tn.startswith(t):
                    score += 1.5
            if t in cn:
                score += 1.0
        if score <= 0:
            continue

        matches.append({
            "document": doc,
            "score": score,
        })

    # Sorting
    reverse = (order == "desc")
    if sort == "relevance":
        matches.sort(key=lambda x: (x["score"], x["document"].get("updated_at") or ""), reverse=True)
    else:
        field = sort
        def keyf(x):
            v = x["document"].get(field)
            if v is None:
                # push None to end for desc, start for asc
                return "" if reverse else "~~~~"
            return v
        matches.sort(key=keyf, reverse=reverse)

    # Cursor pagination: cursor is base64url of offset integer
    offset = 0
    if cursor:
        try:
            pad = "=" * ((4 - len(cursor) % 4) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    raise ValueError()
            else:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(matches)
    page = matches[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    data = [p["document"] for p in page]

    _log("OK")
    return {
        "data": data,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        }
    }

def update_document(document_id, title=None, text=None, status=None, published_at=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_document"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid date-time format", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _append_request_log(status_code, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"out_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso(_now()),
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        policy = _load("rate_limits.json")
        if not isinstance(policy, list) or not policy:
            return None
        p = None
        for r in policy:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                p = r
                break
        if not p:
            return None
        window_s = p.get("window_seconds")
        limit_ = p.get("limit")
        if not isinstance(window_s, int) or not isinstance(limit_, int) or window_s <= 0 or limit_ <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= limit_:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    try:
        rl = _enforce_rate_limit()
        if rl:
            _append_request_log("RATE_LIMIT")
            return rl

        if not isinstance(document_id, str) or not re.match(r"^out_doc_[0-9A-Z]{18,}$", document_id):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "document_id is malformed", field="document_id")
        if title is not None and (not isinstance(title, str) or title.strip() == ""):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
        if text is not None and not isinstance(text, str):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "text must be a string", field="text")
        if status is not None:
            if not isinstance(status, str) or status not in ("draft", "published", "archived", "deleted"):
                _append_request_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "status must be one of: draft, published, archived, deleted", field="status")
        pub_dt, pub_err = _parse_dt(published_at, "published_at")
        if pub_err:
            _append_request_log("VALIDATION_ERROR")
            return pub_err

        if title is None and text is None and status is None and published_at is None:
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "No fields to update")

        documents = _load("documents.json")
        if not isinstance(documents, list):
            documents = []
        doc = next((d for d in documents if isinstance(d, dict) and d.get("id") == document_id), None)
        if not doc:
            _append_request_log("NOT_FOUND")
            return _err("NOT_FOUND", "Document not found", field="document_id")

        # Disallow editing deleted document except idempotent delete
        if doc.get("status") == "deleted" and status != "deleted":
            _append_request_log("CONFLICT")
            return _err("CONFLICT", "Cannot update a deleted document", field="status")

        # Lifecycle transition enforcement (documents lifecycle)
        transitions = {
            "draft": {"published", "archived", "deleted"},
            "published": {"archived", "deleted"},
            "archived": {"published", "deleted"},
            "deleted": set(),
        }
        old_status = doc.get("status")
        new_status = old_status if status is None else status
        if old_status not in transitions:
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Document has invalid status in store", field="status")
        if new_status != old_status and new_status not in transitions.get(old_status, set()):
            _append_request_log("INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition document status from {old_status} to {new_status}", field="status")

        # Validate published_at rules
        if new_status == "published":
            if pub_dt is None:
                # If caller didn't provide, keep existing or set now if missing
                if doc.get("published_at"):
                    try:
                        _ = datetime.datetime.fromisoformat(str(doc.get("published_at")).replace("Z", "+00:00"))
                    except ValueError:
                        pass
                else:
                    pub_dt = _now()
        else:
            # Non-published documents should not have published_at
            if published_at is not None:
                # caller explicitly trying to set it while not published -> invalid combination
                _append_request_log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "published_at can only be set when status is 'published'", field="published_at")
            pub_dt = None

        # Uniqueness: unique(collection_id, title) where status <> 'deleted'
        new_title = doc.get("title") if title is None else title
        if new_title != doc.get("title"):
            for d in documents:
                if not isinstance(d, dict) or d.get("id") == document_id:
                    continue
                if d.get("collection_id") == doc.get("collection_id") and d.get("title") == new_title and d.get("status") != "deleted":
                    _append_request_log("CONFLICT")
                    return _err("CONFLICT", "A non-deleted document with this title already exists in the collection", field="title")

        # Prepare revision snapshot (pre-update snapshot)
        revisions = _load("document_revisions.json")
        if not isinstance(revisions, list):
            revisions = []
        now = _now()
        now_iso = _iso(now)

        def _gen_id(prefix, existing_ids):
            base = int(time.time() * 1000)
            i = 0
            while True:
                cand = f"{prefix}_{base}{i:03d}"
                if cand not in existing_ids:
                    return cand
                i += 1

        existing_rev_ids = {r.get("id") for r in revisions if isinstance(r, dict)}
        rev_id = _gen_id("out_rev", existing_rev_ids)

        old_version = doc.get("version")
        if not isinstance(old_version, int) or old_version < 1:
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Document version is invalid", field="version")

        # Apply update: bump version always on successful update
        new_version = old_version + 1

        # Soft delete behavior
        deleted_at = doc.get("deleted_at")
        if new_status == "deleted":
            if not deleted_at:
                deleted_at = now_iso
        else:
            deleted_at = None

        # Apply fields
        if title is not None:
            doc["title"] = title
        if text is not None:
            doc["text"] = text
        doc["status"] = new_status
        doc["published_at"] = _iso(pub_dt) if pub_dt else (doc.get("published_at") if new_status == "published" else None)
        doc["version"] = new_version
        doc["updated_at"] = now_iso
        doc["deleted_at"] = deleted_at

        # Append revision capturing post-update snapshot at new_version
        rev_row = {
            "id": rev_id,
            "document_id": document_id,
            "workspace_id": doc.get("workspace_id"),
            "version": new_version,
            "title": doc.get("title"),
            "text": doc.get("text"),
            "collection_id": doc.get("collection_id"),
            "parent_document_id": doc.get("parent_document_id"),
            "created_at": now_iso,
        }
        revisions.append(rev_row)

        # Update search index: mark stale or deleted
        sidx = _load("document_search_index.json")
        if not isinstance(sidx, list):
            sidx = []
        srow = next((r for r in sidx if isinstance(r, dict) and r.get("document_id") == document_id), None)

        if new_status == "deleted":
