        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"out_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": "create_collection",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        policy = _load("rate_limits.json")
        if not isinstance(policy, list) or not policy:
            return None
        p = None
        for r in policy:
            if isinstance(r, dict) and r.get("endpoint") == "create_collection":
                p = r
                break
        if not p:
            return None
        window_s = p.get("window_seconds")
        limit_ = p.get("limit")
        if not isinstance(window_s, int) or not isinstance(limit_, int) or window_s <= 0 or limit_ <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
        cnt = 0
        for r in logs:
            if isinstance(r, dict) and r.get("endpoint") == "create_collection":
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    cnt += 1
        if cnt >= limit_:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT")
        return rl

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^out_ws_[0-9A-Z]{18,}$", workspace_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(name, str) or name.strip() == "":
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must not be empty.")
    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if color is not None and not isinstance(color, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "color must be a string.")
    if icon is not None and not isinstance(icon, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "icon must be a string.")
    if position is not None:
        if not isinstance(position, (int, float)):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "position must be a number.")
        if position < 0:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "position must be >= 0.")
    if status is None:
        status = "active"
    if status not in ("active", "archived"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'active' or 'archived'.")

    workspaces = _load("workspaces.json")
    collections = _load("collections.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(collections, list): collections = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context available to perform this operation.")

    # Enforce unique(workspace_id, name) where status <> 'deleted'
    for c in collections:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") == workspace_id and c.get("status") != "deleted" and c.get("name") == name:
            _log("CONFLICT")
            return _err("CONFLICT", "A collection with this name already exists in the workspace.")

    # Position default: max(position)+1 in workspace if not provided
    if position is None:
        maxpos = -1
        for c in collections:
            if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("status") != "deleted":
                p = c.get("position")
                if isinstance(p, (int, float)) and p > maxpos:
                    maxpos = p
        position = maxpos + 1

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        raw = (f"{datetime.datetime.utcnow().timestamp()}_{len(collections)+1}_{os.getpid()}").encode("utf-8")
        enc = base64.b32encode(raw).decode("utf-8").rstrip("=")
        enc = "".join(ch for ch in enc if ch in alphabet)
        if len(enc) < 18:
            enc = (enc + "0" * 18)[:18]
        return f"{prefix}{enc}"

    new_row = {
        "id": _new_id("out_col_"),
        "workspace_id": workspace_id,
        "name": name,
        "description": description,
        "color": color,
        "icon": icon,
        "position": position,
        "status": status,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }

    collections.append(new_row)
    _save("collections.json", collections)

    _log("OK")
    return {"data": new_row}

def delete_collection(collection_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0166000" if __import__("os").path.isdir("./environment_mix/0166000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_collection"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _append_request_log(status_code, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"out_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _iso(_now()),
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        policy = _load("rate_limits.json")
        if not isinstance(policy, list) or not policy:
            return None
        p = None
        for r in policy:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                p = r
                break
        if not p:
            return None
        window_s = p.get("window_seconds")
        limit_ = p.get("limit")
        if not isinstance(window_s, int) or not isinstance(limit_, int) or window_s <= 0 or limit_ <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=window_s)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= limit_:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    try:
        rl = _enforce_rate_limit()
        if rl:
            _append_request_log("RATE_LIMIT")
            return rl

        if not isinstance(collection_id, str) or not re.match(r"^out_col_[0-9A-Z]{20,}$", collection_id):
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "collection_id is malformed", field="collection_id")

        collections = _load("collections.json")
        if not isinstance(collections, list):
            collections = []
        col = next((c for c in collections if isinstance(c, dict) and c.get("id") == collection_id), None)
        if not col:
            _append_request_log("NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found", field="collection_id")

        # Idempotent soft-delete: if already deleted, return it
        if col.get("status") == "deleted":
            _append_request_log("OK", collection_id=collection_id)
            return {"collection": col}

        # Business rule: reject if any documents in collection with status <> 'deleted'
        documents = _load("documents.json")
        if not isinstance(documents, list):
            documents = []
        for d in documents:
            if not isinstance(d, dict):
                continue
            if d.get("collection_id") == collection_id and d.get("status") != "deleted":
                _append_request_log("CONFLICT", collection_id=collection_id)
                return _err("CONFLICT", "Collection cannot be deleted because it has non-deleted documents", rule="delete_collection requires no documents with status <> 'deleted'")

        # Lifecycle transition enforcement for collections
        transitions = {
            "active": {"archived", "deleted"},
            "archived": {"active", "deleted"},
            "deleted": set(),
        }
        old_status = col.get("status")
        if old_status not in transitions:
            _append_request_log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Collection has invalid status in store", field="status")
        if "deleted" not in transitions.get(old_status, set()):
            _append_request_log("INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition collection status from {old_status} to deleted", field="status")

        now_iso = _iso(_now())
        col["status"] = "deleted"
        col["deleted_at"] = now_iso
        col["updated_at"] = now_iso

        _save("collections.json", collections)
        _append_request_log("OK", collection_id=collection_id)
        return {"collection": col}
    except Exception as e:
        _append_request_log("ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

