                if not isinstance(tt, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(tt.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    recent += 1
            if recent >= 1200:
                _log("list_collections", "RATE_LIMIT", "Too many requests")
                return _err("RATE_LIMIT", "Too many requests")
    except Exception:
        pass

    if not isinstance(workspace_id, str) or not re.match(r"^out_ws_[0-9A-Z]{20,}$", workspace_id or ""):
        _log("list_collections", "VALIDATION_ERROR", "workspace_id malformed")
        return _err("VALIDATION_ERROR", "workspace_id is missing or malformed")

    if query is not None and not isinstance(query, str):
        _log("list_collections", "VALIDATION_ERROR", "query type")
        return _err("VALIDATION_ERROR", "query must be a string")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("list_collections", "VALIDATION_ERROR", "status invalid")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("list_collections", "VALIDATION_ERROR", "limit invalid")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    if sort is None:
        sort = "position"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name", "position"):
        _log("list_collections", "VALIDATION_ERROR", "sort invalid")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name, position")

    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("list_collections", "VALIDATION_ERROR", "order invalid")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("list_collections", "VALIDATION_ERROR", "cursor invalid")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("pos:"):
                _log("list_collections", "VALIDATION_ERROR", "cursor malformed")
                return _err("VALIDATION_ERROR", "cursor is malformed")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError()
        except Exception:
            _log("list_collections", "VALIDATION_ERROR", "cursor malformed")
            return _err("VALIDATION_ERROR", "cursor is malformed")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        _log("list_collections", "UNAUTHORIZED", "workspaces store unreadable")
        return _err("UNAUTHORIZED", "No authorized context available")
