    if not isinstance(collections, list):
        _log("list_collections", "UNAUTHORIZED", "collections store unreadable")
        return _err("UNAUTHORIZED", "No authorized context available")

    q = (query or "").strip().lower()
    rows = []
    for c in collections:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != workspace_id:
            continue
        if status is not None and c.get("status") != status:
            continue
        if q:
            name = c.get("name") or ""
            if not isinstance(name, str):
                continue
            if q not in name.lower():
                continue
        rows.append(c)

    def _key(v):
        x = v.get(sort)
        if sort in ("created_at", "updated_at"):
            if isinstance(x, str):
                return x
            return ""
        if sort == "name":
            return (x or "").lower() if isinstance(x, str) else ""
        if sort == "position":
            return x if isinstance(x, (int, float)) else 0
        return x

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"pos:{start+limit}".encode("utf-8")).decode("utf-8")

    _log("list_collections", "OK")
    return {
        "collections": page,
        "total": total,
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more
    }

