        provided["color"] = color
    if icon is not None:
        provided["icon"] = icon
    if position is not None:
        provided["position"] = position
    if status is not None:
        provided["status"] = status

    if not provided:
        _log("update_collection", "VALIDATION_ERROR", "no fields")
        return _err("VALIDATION_ERROR", "No updatable fields were provided")

    if "name" in provided:
        if not isinstance(name, str) or name.strip() == "":
            _log("update_collection", "VALIDATION_ERROR", "name invalid")
            return _err("VALIDATION_ERROR", "name must be a non-empty string")
        provided["name"] = name.strip()

    for field in ("description", "color", "icon"):
        if field in provided and provided[field] is not None and not isinstance(provided[field], str):
            _log("update_collection", "VALIDATION_ERROR", f"{field} invalid")
            return _err("VALIDATION_ERROR", f"{field} must be a string")

    if "position" in provided:
        if not isinstance(position, (int, float)) or position < 0:
            _log("update_collection", "VALIDATION_ERROR", "position invalid")
            return _err("VALIDATION_ERROR", "position must be a number >= 0")

    if "status" in provided:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("update_collection", "VALIDATION_ERROR", "status invalid")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        _log("update_collection", "UNAUTHORIZED", "collections store unreadable")
        return _err("UNAUTHORIZED", "No authorized context available")

    col = None
    idx = None
    for i, c in enumerate(collections):
        if isinstance(c, dict) and c.get("id") == collection_id:
            col = c
            idx = i
            break
    if not col:
        _log("update_collection", "NOT_FOUND", "collection not found")
        return _err("NOT_FOUND", "Collection not found")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == col.get("workspace_id")), None)
    if not ws:
        _log("update_collection", "CONFLICT", "workspace missing for collection")
        return _err("CONFLICT", "Collection cannot be updated due to invalid workspace reference")
    if ws.get("status") in ("deleted", "suspended"):
        _log("update_collection", "CONFLICT", "workspace not active")
        return _err("CONFLICT", "Collection cannot be updated while workspace is not active")

    # Unique(workspace_id, name) where status <> 'deleted'
    if "name" in provided:
        new_name = provided["name"]
        if col.get("status") != "deleted":  # uniqueness applies among non-deleted
            for c in collections:
                if not isinstance(c, dict):
                    continue
                if c.get("id") == collection_id:
                    continue
                if c.get("workspace_id") == col.get("workspace_id") and c.get("status") != "deleted" and c.get("name") == new_name:
                    _log("update_collection", "CONFLICT", "duplicate name")
                    return _err("CONFLICT", "A non-deleted collection with this name already exists in the workspace")

    # Lifecycle transitions
    if "status" in provided:
        cur = col.get("status")
        nxt = provided["status"]
        transitions = {
            "active": set(["archived", "deleted"]),
            "archived": set(["active", "deleted"]),
            "deleted": set([])
        }
        if cur != nxt:
            if cur not in transitions or nxt not in ("active", "archived", "deleted") or nxt not in transitions[cur]:
                _log("update_collection", "INVALID_TRANSITION", "illegal transition")
                return _err("INVALID_TRANSITION", "Illegal collection status transition")

        # If requesting deletion via update, enforce delete_collection rule (no non-deleted docs)
        if cur != "deleted" and nxt == "deleted":
            documents = _load("documents.json")
            if not isinstance(documents, list):
                _log("update_collection", "CONFLICT", "documents store unreadable")
                return _err("CONFLICT", "Collection cannot be deleted due to existing content")
            for d in documents:
                if not isinstance(d, dict):
                    continue
                if d.get("collection_id") == collection_id and d.get("status") != "deleted":
                    _log("update_collection", "CONFLICT", "collection has non-deleted documents")
                    return _err("CONFLICT", "Collection cannot be deleted while it contains non-deleted documents")

    updated = dict(col)
    for k, v in provided.items():
        updated[k] = v

    updated["updated_at"] = ts
    if "status" in provided and provided["status"] == "deleted" and col.get("status") != "deleted":
        updated["deleted_at"] = ts
    if "status" in provided and provided["status"] != "deleted":
        # If resurrecting from deleted is not allowed by lifecycle; we already block it.
        # For active/archived, ensure deleted_at cleared if previously null or not.
        if updated.get("status") in ("active", "archived"):
            # keep deleted_at as-is unless the record was previously deleted (shouldn't happen due to lifecycle)
            pass

    collections[idx] = updated
    _save("collections.json", collections)

    _log("update_collection", "OK")
    return {"collection": updated}
